export const CATEGORIES = ["Civic", "Literar", "Creștin", "Științific", "Filosofic", "Impostor"];

export const PROMPTS = [
 {category:"Civic",type:"desen",text:"Desenează o scenă clară despre viața în comunitate și ajutorul oferit vecinilor."},
 {category:"Civic",type:"text",text:"Scrie un motto original despre responsabilitatea față de ceilalți și binele întregii comunități."},
 {category:"Literar",type:"desen",text:"Desenează o scenă inspirată de o poveste, de un mit sau de o carte cunoscută."},
 {category:"Literar",type:"text",text:"Scrie o idee originală despre puterea cărților, imaginației și educației în viața oamenilor."},
 {category:"Creștin",type:"desen",text:"Desenează un simbol al credinței, al speranței sau al iubirii față de aproapele tău."},
 {category:"Creștin",type:"text",text:"Scrie un îndemn sincer despre bunătate, iertare și grija față de oamenii din jur."},
 {category:"Științific",type:"desen",text:"Desenează o descoperire importantă sau un instrument științific care ajută omenirea să progreseze."},
 {category:"Științific",type:"text",text:"Scrie o propoziție argumentată despre importanța dovezilor și a observațiilor repetate cu atenție."},
 {category:"Filosofic",type:"desen",text:"Desenează un simbol sugestiv al cunoașterii de sine, al libertății și al rațiunii."},
 {category:"Filosofic",type:"text",text:"Scrie o idee personală despre libertatea de gândire, rațiune și sensul propriilor alegeri."},
 {category:"Impostor",type:"desen",text:"Desenează o creatură fantastică într-o situație amuzantă, folosind cât mai multe detalii originale."},
 {category:"Impostor",type:"text",text:"Scrie o idee absurdă și amuzantă despre o întâmplare imposibilă dintr-un univers imaginar."}
];

